R("async function csvAiRun(only){const P=ADM.csv;if(!P||P.stage!=='review'||!sample||P.busy)return;\n const queue=P.items.filter(o=>(only?only.includes(o):true)&&needsAI(o).length);if(!queue.length)return;P.busy=true;P.err='';let done=0;\n", "async function csvAiRun(only){const P=ADM.csv;if(!P||P.stage!=='review'||!sample||P.busy)return;\n const queue=P.items.filter(o=>(only?only.includes(o):true)&&needsAI(o).length);if(!queue.length)return;P.busy=true;P.err='';let done=0;\n if(sample.manual){const needs=queue.map(o=>needsAI(o));queue.forEach(o=>o._st='run');csvRefresh();\n  const prompt=`มี Culture ${queue.length} รายการ ทำแต่ละรายการตามคำสั่งของรายการนั้น แล้วตอบเป็น JSON array เดียวที่มี ${queue.length} object เรียงตามลำดับรายการ (object ที่ 1 = รายการที่ 1)\\n\\n`+queue.map((o,k)=>`===== รายการที่ ${k+1} =====\\n`+csvAiPrompt(o,needs[k])).join('\\n\\n');\n  try{let r=await sample.json(prompt,{cache:false,title:'เติมช่องที่ว่างให้ Culture จากไฟล์ CSV ทั้งหมด '+queue.length+' รายการในครั้งเดียว'});if(!Array.isArray(r))r=[r];\n   queue.forEach((o,k)=>{csvApplyAi(o,r[k],needs[k]);o._st=needsAI(o).length?'part':'ok'})}\n  catch(e){queue.forEach(o=>o._st=e&&e.code==='cancelled'?'':'fail');if(!e||e.code!=='cancelled')P.err=sampleErr(e)}\n  P.busy=false;csvRefresh();return}\n")
