R('function csvIntro(){return`<section class="panel csvp"><div class="csvh"><h2>นำเข้า Culture จาก CSV</h2><button class="link" data-act="csvCancel">ปิด</button></div>\n <p class="note">ขั้นต่ำมีแค่ชื่อ Culture แถวละ 1 Culture จะเป็นภาษาไทย อังกฤษ หรือทั้งสองภาษาก็ได้ ส่วนที่ขาด${sample?\' AI จะแปลชื่อและเขียนให้ แล้วให้คุณตรวจแก้ก่อนนำเข้า\':\' แก้เองได้ก่อนนำเข้า\'}</p>\n <div class="lv"><div class="lvc"><span class="lvn">แบบง่าย</span><b>ชื่อ Culture อย่างเดียวก็พอ</b><p>ใส่ Subculture หรือ Hashtag เพิ่มได้ ช่วยให้ AI เข้าใจความหมายได้ตรงขึ้น</p><code>name_th, name_en, subcultures, hashtags</code><button class="btn quiet sm" data-tpl="basic">ดาวน์โหลดตัวอย่างแบบง่าย</button></div>\n <div class="lvc"><span class="lvn">แบบครบ</span><b>ใส่ทุกช่องเอง</b><p>Definition ฉายา คำอธิบาย จุดแข็ง ฯลฯ ช่องไหนเว้นว่าง${sample?\' AI เติมให้\':\' แก้เองได้\'} ข้อมูลที่ใส่มาจะไม่ถูกเปลี่ยน</p><code>name_th, name_en, definition, …</code><button class="btn quiet sm" data-tpl="full">ดาวน์โหลดตัวอย่างแบบครบ</button></div></div>\n <p class="note">หลายค่าในช่องเดียว คั่นด้วย <b>,</b> <b>;</b> หรือ <b>|</b> · Hashtag ใส่หรือไม่ใส่ # ก็ได้ · หัวคอลัมน์ใช้ไทยหรืออังกฤษก็ได้ เช่น ชื่อไทย, ชื่ออังกฤษ, Subculture, แฮชแท็ก</p>\n ${ADM.tplText?`<textarea class="tpl" id="tplText" readonly>${esc(ADM.tplText)}</textarea><div class="row"><button class="btn quiet sm" data-act="tplCopy">คัดลอก</button><span class="note">คัดลอกไปวางในไฟล์ .csv แล้วบันทึกเป็น UTF-8</span></div>`:\'\'}\n <div class="row" style="margin-top:14px"><button class="btn primary sm" data-act="csvFile">เลือกไฟล์ CSV</button></div></section>`}\n', 'function csvIntro(){return`<section class="panel csvp"><div class="csvh"><h2>เพิ่ม Culture ขององค์กร</h2><button class="link" data-act="csvCancel">ปิด</button></div>\n <p class="note">พิมพ์ชื่อ Culture <b>ช่องละ 1 ชื่อ</b> ภาษาไทยหรืออังกฤษก็ได้ กด Enter เพื่อไปช่องถัดไป หรือคัดลอกคอลัมน์ชื่อจาก Excel มาวางในช่องแรกได้ทั้งก้อน${sample?\' จากนั้นให้ AI เขียนความหมายและรายละเอียดที่เหลือ\':\'\'} แล้วตรวจแก้ก่อนนำเข้า</p>\n <ol class="nrows" id="nameList">${nameRowsHTML([\'\',\'\',\'\',\'\',\'\'])}</ol><button class="link" data-act="nameAdd">+ เพิ่มช่อง</button>\n <div class="row" style="margin-top:12px"><button class="btn primary sm" data-act="nameList">ต่อไป: ตรวจรายชื่อ →</button><span class="note" id="nameListN"></span></div>\n <details class="csvalt"><summary>มีไฟล์ Excel หรือ CSV อยู่แล้ว? นำเข้าจากไฟล์</summary>\n <div class="lv"><div class="lvc"><span class="lvn">แบบง่าย</span><b>ชื่อ Culture อย่างเดียวก็พอ</b><p>ใส่ Subculture หรือ Hashtag เพิ่มได้ ช่วยให้ AI เข้าใจความหมายได้ตรงขึ้น</p><code>name_th, name_en, subcultures, hashtags</code><button class="btn quiet sm" data-tpl="basic">ดาวน์โหลดตัวอย่างแบบง่าย</button></div>\n <div class="lvc"><span class="lvn">แบบครบ</span><b>ใส่ทุกช่องเอง</b><p>Definition ฉายา คำอธิบาย จุดแข็ง ฯลฯ ช่องไหนเว้นว่าง${sample?\' AI เติมให้\':\' แก้เองได้\'} ข้อมูลที่ใส่มาจะไม่ถูกเปลี่ยน</p><code>name_th, name_en, definition, …</code><button class="btn quiet sm" data-tpl="full">ดาวน์โหลดตัวอย่างแบบครบ</button></div></div>\n <p class="note">หลายค่าในช่องเดียว คั่นด้วย <b>,</b> <b>;</b> หรือ <b>|</b> · Hashtag ใส่หรือไม่ใส่ # ก็ได้ · หัวคอลัมน์ใช้ไทยหรืออังกฤษก็ได้ เช่น ชื่อไทย, ชื่ออังกฤษ, Subculture, แฮชแท็ก · บันทึกไฟล์เป็น CSV UTF-8</p>\n ${ADM.tplText?`<textarea class="tpl" id="tplText" readonly>${esc(ADM.tplText)}</textarea><div class="row"><button class="btn quiet sm" data-act="tplCopy">คัดลอก</button><span class="note">คัดลอกไปวางในไฟล์ .csv แล้วบันทึกเป็น UTF-8</span></div>`:\'\'}\n <div class="row" style="margin-top:14px"><button class="btn quiet sm" data-act="csvFile">เลือกไฟล์ CSV</button></div></details></section>`}\n')
R('function csvPreview(){', 'const NAME_PH=[\'เช่น Trustworthy\',\'เช่น Innovative\',\'เช่น กล้าคิดกล้าทำ\',\'เช่น ทำงานเป็นทีม\',\'เช่น Customer First\'];\nconst nameRowsHTML=vals=>vals.map((v,k)=>`<li><span class="nn">${k+1}</span><input data-nrow value="${esc(v)}" placeholder="${NAME_PH[k]||\'ชื่อ Culture\'}" aria-label="Culture ที่ ${k+1}"><button class="nx" data-nrm aria-label="ลบช่อง ${k+1}">×</button></li>`).join(\'\');\nconst nameVals=()=>[...document.querySelectorAll(\'#nameList [data-nrow]\')].map(i=>i.value);\nfunction setNameRows(vals,focus){const l=$(\'nameList\');if(!l)return;vals=vals.slice(0,MAX_C);if(!vals.length)vals=[\'\'];l.innerHTML=nameRowsHTML(vals);nameCount();if(focus!=null){const i=l.querySelectorAll(\'[data-nrow]\')[Math.min(focus,vals.length-1)];if(i)i.focus()}}\nfunction nameCount(){const n=nameVals().filter(v=>v.trim()).length,el=$(\'nameListN\');if(el)el.textContent=n?n+\' Culture\':\'\'}\ndocument.addEventListener(\'input\',e=>{if(e.target.matches&&e.target.matches(\'#nameList [data-nrow]\'))nameCount()});\ndocument.addEventListener(\'keydown\',e=>{const t=e.target;if(!t.matches||!t.matches(\'#nameList [data-nrow]\'))return;const all=[...document.querySelectorAll(\'#nameList [data-nrow]\')],k=all.indexOf(t);\n if(e.key===\'Enter\'){e.preventDefault();if(k===all.length-1){const v=nameVals();v.push(\'\');setNameRows(v,k+1)}else all[k+1].focus()}\n else if(e.key===\'Backspace\'&&!t.value&&all.length>1){e.preventDefault();const v=nameVals();v.splice(k,1);setNameRows(v,Math.max(0,k-1))}});\ndocument.addEventListener(\'paste\',e=>{const t=e.target;if(!t.matches||!t.matches(\'#nameList [data-nrow]\'))return;const txt=(e.clipboardData||window.clipboardData).getData(\'text\');if(!/\\r?\\n/.test(txt.trim()))return;e.preventDefault();\n const add=txt.split(/\\r?\\n/).map(l=>l.split(\'\\t\')[0].replace(/^\\s*(?:\\d+[.)]|[-•*])\\s*/,\'\').trim()).filter(Boolean),v=nameVals(),k=[...document.querySelectorAll(\'#nameList [data-nrow]\')].indexOf(t);\n v.splice(k,1,...add);const rest=v.slice(k+add.length).filter(x=>x.trim());setNameRows([...v.slice(0,k+add.length),...rest,\'\'],k+add.length)});\ndocument.addEventListener(\'click\',e=>{const rm=e.target.closest(\'#nameList [data-nrm]\');if(rm){const all=[...document.querySelectorAll(\'#nameList [data-nrm]\')],v=nameVals();v.splice(all.indexOf(rm),1);setNameRows(v);return}\n if(e.target.closest(\'[data-act=nameAdd]\')){const v=nameVals();if(v.length>=MAX_C){toast(\'ใส่ได้สูงสุด \'+MAX_C+\' Culture\');return}v.push(\'\');setNameRows(v,v.length-1)}});\nfunction nameListToCsv(t){const rows=String(t).split(/\\r?\\n/).map(l=>l.split(\'\\t\')[0].replace(/^\\s*(?:\\d+[.)]|[-•*])\\s*/,\'\').trim()).filter(Boolean);\n return rows.length?\'name\\n\'+rows.map(r=>\'"\'+r.replace(/"/g,\'""\')+\'"\').join(\'\\n\'):\'\'}\ndocument.addEventListener(\'click\',e=>{if(!e.target.closest(\'[data-act=nameList]\'))return;const csv=nameListToCsv(nameVals().join(\'\\n\'));if(!csv){toast(\'พิมพ์ชื่อ Culture อย่างน้อย 1 บรรทัด\');return}\n ADM.csv=analyzeCSV(csv,\'รายชื่อที่พิมพ์\');renderAdmin();const p=$(\'admBody\').querySelector(\'.csvp\');if(p)p.scrollIntoView({block:\'start\'});if(ADM.csv.stage===\'review\'&&sample&&!sample.manual)csvAiRun()});\nfunction csvPreview(){')
